  useEffect(() => {
    markAsRead().catch(console.error);
    room?.isDirect().then(setIsDirect).catch(console.error);
  }, [room, markAsRead]);

  return {
    events,
    timelineRef,
    isPaginatingRef,
    reachedStartRef,
    isDirect,
    loadMoreMessages,
    markAsRead,
  };
};

